import type {Metadata} from "next";import Link from "next/link";import {notFound} from "next/navigation";import {getGuide,guides} from "@/data/guides";import {site} from "@/lib/site";
type Props={params:Promise<{slug:string}>};export function generateStaticParams(){return guides.map(g=>({slug:g.slug}))}export async function generateMetadata({params}:Props):Promise<Metadata>{const {slug}=await params;const g=getGuide(slug);if(!g)return{};return{title:g.title,description:g.description,alternates:{canonical:`/guides/${g.slug}/`},openGraph:{type:"article",title:g.title,description:g.description,publishedTime:g.publishedAt,modifiedTime:g.updatedAt}}}
export default async function GuidePage({params}:Props){const {slug}=await params;const g=getGuide(slug);if(!g)notFound();const schema={"@context":"https://schema.org","@type":"Article",headline:g.title,description:g.description,datePublished:g.publishedAt,dateModified:g.updatedAt,inLanguage:"si",author:{"@type":"Organization",name:site.name},publisher:{"@type":"Organization",name:site.name},mainEntityOfPage:`${site.url}/guides/${g.slug}/`};return <><script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(schema)}}/><article className="guideArticle"><header><div className="shell narrow"><nav className="crumbs"><Link href="/">මුල් පිටුව</Link><span>›</span><Link href="/guides/">Guides</Link><span>›</span><b>{g.category}</b></nav><span>{g.category.toUpperCase()} · {g.readTime}</span><h1>{g.title}</h1><p>{g.description}</p><div className="guideMeta">Published {g.publishedAt} · Updated {g.updatedAt}</div></div></header><div className="shell narrow articleBody"><p className="lead">{g.lead}</p>{g.sections.map((s,i)=><section key={i}><h2>{s.heading}</h2>{s.paragraphs?.map((p,j)=><p key={j}>{p}</p>)}{s.steps&&<ul>{s.steps.map((x,j)=><li key={j}>{x}</li>)}</ul>}</section>)}<aside className="practiceCta"><b>දැන් paper එකක් practice කරමුද?</b><p>විෂය, වසර සහ මාධ්‍ය තෝරාගෙන නිල O/L paper එකක් සොයන්න.</p><Link href="/ol-past-papers/">O/L Papers සොයන්න →</Link></aside></div></article></>}
